csui.define('dctmw/overrides/csui/controls/toolbar/toolitems.view',[
  'require',
  'nuc/lib/underscore',
  'csui/controls/toolbar/toolbar.view' //Unnecessary dependency to make sure in release mode, csui-view-support bundle is loaded before accessing toolitems.view
], function(require, _){
  
  //Ask CSUI to expose or fix
  csui.require([
    'csui/controls/toolbar/toolitems.view'
  ], function(ToolitemsView){
    const origChildViewOptions = ToolitemsView.prototype.childViewOptions;
    
    ToolitemsView.prototype.childViewOptions = function(model) {
      const childOptions = origChildViewOptions.call(this, model);
      _.defaults(childOptions, _.pick(this.options, ['renderIconAndText']));
      return childOptions;
    }
  });
  
});