import module from 'module';
import _ from 'nuc/lib/underscore';
import $ from 'nuc/lib/jquery';
import {Object as MarionetteObject} from 'nuc/lib/marionette';
import {Model, Collection} from 'nuc/lib/backbone';
import logger from 'nuc/utils/log';
import utils from 'dctmw/utils/utils';
import DctmPrefStoreServerAdaptorMixin from 'dctmw/server.adaptors/models/dctmw/dctm.pref.store.server.adaptor.mixin';

const DEFAULT_STORE_NAME = 'sv', SERVER_PROP_NAME = 'preference-content';
const DEFAULT_STORE_NS = DEFAULT_STORE_NAME;

const log = logger(module.id);
let {storeName = DEFAULT_STORE_NAME, enablePersistence = true} = module.config();
if(!utils.isNonEmptyString(storeName)) {
  storeName = DEFAULT_STORE_NAME;
}
storeName = storeName.toLowerCase();

function isEnabled() {
  return enablePersistence === true;
}

class StoteImpl extends MarionetteObject {
  #properties={};
  #moduleBaseUrl;
  #tsPendingUpdate = 0;
  #tsLastUpdate = 0;
  #updateInProgress = false;
  #storeEnsured = false;
  #acceptingStoreChanges = true;
  #localStore = null;
  
  constructor(options={}) {
    options.storeName = storeName;
    options.enabled = isEnabled();
    super(options);
    
    this.makePrefStore(options);
    log.info(`Persistence store is named: '${this.options.storeName}' and it is '${isEnabled() ? 'enabled': 'disabled'}'`) && console.log(log.last);
    this.#moduleBaseUrl = $('<a>').prop('href', window.sv.config.svfPackagePath).prop('href');
    log.debug(`Module base URL: ${this.#moduleBaseUrl}`) && console.log(log.last);
    
    $(document).on('pageidle', () => {
      this.updateStore();
    });
  }
  
  toJSON(tsUpdate) {
    const out = {};
    out[SERVER_PROP_NAME] = JSON.stringify({
      data: Object.keys(this.#properties).reduce((acc, k) => {
        acc[k] = this.#properties[k].toJSON();
        return acc;
      }, {}),
      ts: tsUpdate
    });
    return out;
  }
  
  _getCallerNS() {
    const e = new Error('test');
    const sTrace = e.stack.split('\n').filter(entry => entry.indexOf(this.#moduleBaseUrl) >= 0).map(e => e.trim());
    
    if(sTrace.length < 1) {
      return DEFAULT_STORE_NS;
    }
    
    const getFilePathFromTraceEntry = (e) => {
      e = e.substring(e.indexOf(this.#moduleBaseUrl) + this.#moduleBaseUrl.length);
      const eParts = e.split(':');
      e = eParts[0].split('').reverse().join('');
      e = e.substring(e.indexOf('sj.')).split('').reverse().join('');
      return e.startsWith('/') ? e.substring(1) : e;
    };
    
    let lastFilePath = getFilePathFromTraceEntry(sTrace[0]);
    let ns;
    let firstNonMatchingIndex;
    
    for(let i = 1; i<sTrace.length; i++) {
      let filePath = getFilePathFromTraceEntry(sTrace[i]);
      if(filePath !== lastFilePath) {
        log.debug(`File path with deviation : ${filePath}`) && console.log(log.last);
        firstNonMatchingIndex = i;
        ns = filePath.substring(0, filePath.indexOf('/'));
        break;
      }
    }
    
    const prevTrace = sTrace[firstNonMatchingIndex - 1];
    if(prevTrace.indexOf('getModelStore') < 0 && prevTrace.indexOf('getCollectionStore') < 0) {
      const filePath = getFilePathFromTraceEntry(prevTrace);
      log.debug(`Deviation pattern adjusted to : ${filePath}`) && console.log(log.last);
      ns = filePath.substring(0, filePath.indexOf('/'));
    }
    
    return utils.isNonEmptyString(ns) ? ns : DEFAULT_STORE_NS;
  }
  
  _getNormalizedStoreKey(key) {
    const normKey = `${this._getCallerNS()}:${key}`;
    log.debug(`Normalized storage access key is ${normKey} for given key ${key}`) && console.log(log.last);
    return normKey;
  }
  
  _hasUnsavedChanges() {
    return this.#tsPendingUpdate >= this.#tsLastUpdate;
  }
  
  _markPendingUpdate() {
    if(this.#acceptingStoreChanges) {
      this.#tsPendingUpdate = new Date().getTime();
      if (this.#storeEnsured) {
        this.#getLocalStore().set('data', this.toJSON(this.#tsPendingUpdate));
      }
      this._attachUnloadEventListener();
    }
  }
  
  _beforeUnloadEventName() {
    return 'beforeunload.pstore';
  }
  
  _attachUnloadEventListener() {
    const eName = this._beforeUnloadEventName();
    $(window).off(eName).on(eName, () => {
      this.updateStore({immediate: this._hasUnsavedChanges()});
    });
  }
  
  _detachUnloadEventListener() {
    $(window).off(this._beforeUnloadEventName());
  }
  
  _attachModelEvents(model) {
    this.listenTo(model, 'change', this._markPendingUpdate);
  }
  
  _detachModelEvents(model) {
    this.stopListening(model, 'change');
  }
  
  _attachCollectionEvents(col) {
    this.listenTo(col, 'reset update change', this._markPendingUpdate);
  }
  
  _detachCollectionEvents(col) {
    this.stopListening(col, 'reset update change');
  }
  
  _collateDataIntoModel(model, data) {
    if((model instanceof Model) && _.isObject(data) && !_.isEmpty(data)) {
      const nonExistingValues = {};
      Object.keys(data).forEach(k => {
        if(!model.has(k)) {
          nonExistingValues[k] = data[k];
        }
      });
      if(!_.isEmpty(nonExistingValues)) {
        model.set(nonExistingValues);
      }
    }
  }
  
  _collateDataIntoCollection(col, data) {
    if((col instanceof Collection) && _.isArray(data) && data.length) {
      const addableModelsData = [];
      data.forEach((e, i) => {
        if(i < col.length) {
          this._collateDataIntoModel(col.at(i), e);
        } else if(_.isObject(e) && !_.isEmpty(e)) {
          addableModelsData.push(e);
        }
      });
      if(addableModelsData.length) {
        col.add(addableModelsData);
      }
    }
  }
  
  getModel(key, options={}) {
    const normalizedKey = this._getNormalizedStoreKey(key);
    let store = this.#properties[normalizedKey];
    if(!store && options.create !== false) {
      store = new Model({});
      this.#properties[normalizedKey] = store;
      this._attachModelEvents(store);
    }
    if(store && !(store instanceof Model)) {
      throw new Error(`Accessor type mismatch: ${key} is not a model store`);
    }
    
    this._collateDataIntoModel(store, options.defaultValues);
    
    return store;
  }
  
  getCollection(key, options={}) {
    const normalizedKey = this._getNormalizedStoreKey(key);
    let store = this.#properties[normalizedKey];
    if(!store && options.create !== false) {
      store = new Collection([]);
      this.#properties[normalizedKey] = store;
      this._attachCollectionEvents(store);
    }
    
    if(store && !(store instanceof Collection)) {
      throw new Error(`Accessor type mismatch: ${key} is not a collection store`);
    }
    
    this._collateDataIntoCollection(store, options.defaultValues);
    
    return store;
  }
  
  initFrom(str) {
    if(utils.isNonEmptyString(str)) {
      log.debug(`Initializing persistence store : '${this.options.storeName}' from content "${str}"`) && console.log(log.last);
      try {
        const storedJson = JSON.parse(str);
        const data = storedJson?.data || {};
        Object.keys(data).forEach(k => {
          const v = data[k];
          let store = this.#properties[k];
          if (_.isArray(v)) {
            if (!store) {
              store = new Collection();
            }
          } else if (_.isObject(v)) {
            if (!store) {
              store = new Model();
            }
          }
          
          this.#properties[k] = store;
          if (store instanceof Model) {
            this._detachModelEvents(store);
            store.clear({silent: true});
            store.set(v);
            this._attachModelEvents(store);
          } else if (store instanceof Collection) {
            this._detachCollectionEvents(store);
            store.reset(v);
            this._attachCollectionEvents(store);
          }
        });
        this.#tsLastUpdate = storedJson.ts || new Date().getTime();
      } catch(e) {
        log.warn(`"${str}" is not JSON. Persistent store : '${this.options.storeName}' is effectively reset to empty state`) && console.warn(log.last);
      }
    } else if(str !== '') {
      throw new Error('Can not init from other than string input');
    }
  }
  
  createStore() {
    const dfd = $.Deferred();
    
    this._addStoreEnsureMarker(dfd);
    if(isEnabled()) {
      log.debug(`Creating persistent store: '${this.options.storeName}'`);
      this.#updateInProgress = true;
      const tsUPD = new Date().getTime();
      this._createStore({data: this.toJSON(tsUPD)}).done(()=>{
        this.#tsLastUpdate = tsUPD;
        this._detachUnloadEventListener();
        dfd.resolve();
      }).fail(dfd.reject).always(()=>{
        this.#updateInProgress = false;
      });
    } else {
      dfd.resolve();
    }
    
    return dfd.promise();
  }
  
  fetchStore() {
    const dfd = $.Deferred();
    
    this._addStoreEnsureMarker(dfd);
    if(isEnabled()) {
      log.debug(`Fetching persistent store: '${this.options.storeName}'`);
      this._fetchStore({}).done((resp) => {
        const serverPref = resp?.[SERVER_PROP_NAME];
        const data = this.#lookupLocalData(serverPref);
        const syncPref = serverPref !== data;
        try {
          this.initFrom(data ?? '');
          if (syncPref && data) {
            this.updateStore({ skipBackup: true, immediate: true })
              .always(dfd.resolve);
          }else{
            dfd.resolve();
          }
        } catch (e) {
          dfd.reject(e);
        }
      }).fail(dfd.reject);
    } else {
      dfd.resolve();
    }
    
    return dfd.promise();
  }

  #lookupLocalData(serverPref) {
    //decide whether to use local version or server version
    const lStore = this.#getLocalStore();
    const localData = lStore.get('data');

    if (localData?.[SERVER_PROP_NAME] && serverPref) {
      try {
        const localPrefObj = JSON.parse(localData[SERVER_PROP_NAME]);
        const serverPrefObj = JSON.parse(serverPref);
        if (serverPrefObj.ts && localPrefObj.ts <= serverPrefObj.ts) {
          lStore.destroy();
        } else {
          return localData[SERVER_PROP_NAME];
        }
      } catch (e) {
        log.warn(`Failed to parse the string, so skipping local data restore, and removing local data`) && console.warn(log.last);
        lStore.destroy();
      }
    }
    return serverPref;
  }

  #getLocalStore(){
    if(!this.#localStore){
      this.#localStore = utils.getLocalStore(this.options.storeName);
    }
    return this.#localStore;
  }
  
  updateStore(options={}) {
    const dfd = $.Deferred();
    
    const { immediate=false, skipBackup = false } = options;
    if(isEnabled() && (immediate || (!this.#updateInProgress && this._hasUnsavedChanges()))) {
      this.#updateInProgress = true;
      this._addStoreEnsureMarker(dfd);
      
      log.debug(`Updating persistent store: '${this.options.storeName}'`);
      const tsUPD = new Date().getTime();
      const storeData  = this.toJSON(tsUPD);
      
      //Also store this in local storage so that in case of forced xhr termination/failure, we can recover from it
      if (!skipBackup) {
        this.#getLocalStore().set('data', storeData);
      }

      this._updateStore({data: storeData})
        .done(() => {
          this.#updateInProgress = false;
          this.#tsLastUpdate = tsUPD;
          this._detachUnloadEventListener();
          this.#getLocalStore().destroy();
          dfd.resolve();
        }).fail((xhr, textStatus, error) => {
          this._storeApiFailureHandler(xhr, textStatus, error)
            .always(() => {
              this.#updateInProgress = false;
            })
            .done(() => {
              this.#tsLastUpdate = tsUPD;
              this._detachUnloadEventListener();
              dfd.resolve();
            }).fail(dfd.reject);
        });
    } else {
      dfd.resolve();
    }
    
    return dfd.promise();
  }
  
  ensureStore() {
    const dfd = $.Deferred();
    
    if(!this.#storeEnsured) {
      log.info(`Ensuring persistence store: '${this.options.storeName}'`);
      this._addStoreEnsureMarker(dfd);
      this.fetchStore()
        .done(dfd.resolve)
        .fail((xhr, textStatus, error) => {
          this._storeApiFailureHandler(xhr, textStatus, error).done(dfd.resolve).fail(dfd.reject);
        });
    } else {
      log.debug(`Persistent store: '${this.options.storeName}' already ensured.`);
      dfd.resolve();
    }
    
    return dfd.promise();
  }
  
  resetStore() {
    const dfd = $.Deferred();
    const fnRetry = () => {
      this.resetStore().done(dfd.resolve).fail(dfd.reject);
    };
    
    if(isEnabled()) {
      this.#acceptingStoreChanges = false; // Stop accepting changes till store is effectively deleted
      if(this.#storeEnsured && !this.#updateInProgress) {
        this._removeStore() // Delete the entire store until we have a change of requirement
          .fail(() => {
            setTimeout(fnRetry, 1000);
          }).done(() => {
          this.#tsLastUpdate = new Date().getTime(); // To discard pending changes if any
          this.#acceptingStoreChanges = true;
          dfd.resolve();
        });
      } else {
        setTimeout(fnRetry, 1000);
      }
    } else {
      dfd.resolve();
    }
    
    return dfd.promise();
  }
  
  _storeApiFailureHandler(xhr, textStatus, error) {
    const dfd = $.Deferred();
    
    const {status} = xhr;
    if(status === 404) {
      log.info(`Persistence store: '${this.options.storeName}' does not exist, will create it and cleaning the local data`) && console.log(log.last);
      this.#getLocalStore().destroy();
      this.createStore().done(dfd.resolve).fail(dfd.reject);
    } else {
      log.error(`unable to save the data to persistence store: '${this.options.storeName}'`) && console.error(log.last);
      dfd.reject(error);
    }
    
    return dfd.promise();
  }
  
  _addStoreEnsureMarker(dfd) {
    dfd.promise().done(() => {
      this.#storeEnsured = true;
    });
  }
}
DctmPrefStoreServerAdaptorMixin.mixin(StoteImpl.prototype);

/**
 *
 * @module "dctmw/utils/persistent.store"
 *
 */

/**
 *
 * @class
 * @classdesc Interface to a general purpose data store API backed by server-side persistence.
 * @typicalname persistentStore
 *
 */

class PersistentStore {
  #storeImpl;
  
  constructor() {
    this.#storeImpl = new StoteImpl();
  }
  
  /**
   * Returns a persistent store that is represented through a Backbone model instance. Any attribute change in the model is
   * tracked and periodically saved through server side persistence. If a store does not exist by the given `key`, it
   * is created first and then returned.
   *
   * @param {String} key - Identifier used to refer to the model store.
   * @param {ModelStoreOptions} options - Retrieval option for the store.
   * @returns {external:BackboneModel} The store instance
   *
   * @example <caption>Creating an empty model store</caption>
   * import persistentStore from 'dctmw/utils/persistent.store';
   *
   * // Assuming 'model1' does not already exist from earlier times
   * const modelStore = persistentStore.getModelStore('model1');
   * console.log(modelStore.isEmpty()); // Prints true
   *
   * modelStore.set('key1', true);
   * // after this line, since now we've saved some data into the store, the console.log() line from above will print false after application reload
   *
   * @example <caption>Creating model store with initial values</caption>
   * import persistentStore from 'dctmw/utils/persistent.store';
   *
   * // Assuming 'model2' does not already exist from earlier times
   * const modelStore2 = persistentStore.getModelStore('model2', {
   *   defaultValues: {
   *     m2k1: true,
   *     m2k2: false
   *   }
   * });
   *
   * console.log(modelStore2.isEmpty()); // Prints false as the store is created with some default values.
   * console.log(modelStore2.get('m2k1')); // Prints true as that was the value set through default
   *
   * modelStore2.set('m2k1', false);
   * // After this line, m2k1 in store model2 will continue to have value false even after application reload.
   * // So the line console.log(modelStore2.get('m2k1')) from above will print false from next application reload onwards
   *
   * @example <caption>Accessing model store with value collation</caption>
   * import persistentStore from 'dctmw/utils/persistent.store';
   *
   * // Assuming the modelStore2 from previous example still carries stored values {m2k1: false, m2k2: false}
   * const modelStore2 = persistentStore.getModelStore('model2', {
   *   defaultValues: {
   *     m2k1: true,
   *     m2k3: true
   *   }
   * });
   *
   * console.log(modelStore2.get('m2k1')); // Prints false, as m2k1 is a pre-existing key within the store, so the supplied default value from above line is ignored
   * console.log(modelStore2.get('m2k3')); // Prints true, as m2k3 did not exist earlier, it is now initialized from the supplied default value from above
   */
  getModelStore(key, options) {
    return this.#storeImpl.getModel(key, options);
  }
  
  /**
   * Returns a persistent store that is represented through a Backbone collection instance. Any chanage in the collection, like model add/delete and each model's attribute
   * changes are tracked and periodically saved through server side persistence. If a store does not exist by the given `key`, it is created first and then returned.
   *
   * @param {String} key - Identifier used to refer to the collection store.
   * @param {CollectionStoreOptions} options - Retrieval option for the store.
   * @returns {external:BackboneCollection} The store instance
   *
   * @example <caption>Creating an empty collection store</caption>
   * import persistentStore from 'dctmw/utils/persistent.store';
   *
   * // Assuming 'col1' does not already exist from earlier times
   * const colStore1 = persistentStore.getCollectionStore('col1');
   * console.log(colStore1.length); // Prints 0 as no model exists
   *
   * colStore1.add([
   *   {id: 'one'},
   *   {id: 'two'}
   * ]);
   *
   * console.log(colStore1.length); // Prints 2 as two models are added
   * // The above line will continue to print 2 even after application reload
   *
   * @example <caption>Creating a collection store with initial data</caption>
   * import persistentStore from 'dctmw/utils/persistent.store';
   *
   * // Assuming 'col2' does not already exist from earlier times
   * const colStore2 = persistentStore.getCollectionStore('col2', {
   *   defaultValues: [
   *     {id: 1},
   *     {id: 2},
   *     {id: 3}
   *   ]
   * });
   *
   * console.log(colStore2.length); // Prints 3 as store was created with 3 models inside
   * colStore2.at(0).set('id', 4);
   * // This line onwards the first model's id will continue to have value 4 even after application reload
   *
   * @example <caption>Accessing collection store with data collation</caption>
   * import persistentStore from 'dctmw/utils/persistent.store';
   *
   * // Assuming colStore2 from previous example still carries 3 stored models.
   * const colStore2 = persistentStore.getCollectionStore('col2', {
   *   defaultValues: [
   *     {id: 1, key1: 1},
   *     {id: 2},
   *     {id: 3},
   *     {id: 10}
   *   ]
   * });
   *
   * console.log(colStore2.length); // Prints 4, as the result of the new model {id: 10} getting added after collation
   * console.log(colStore2.at(0).get('id')); // Prints 4, as id was an existing key carrying value 4 from before, the default value supplied above is ignored
   * console.log(colStore2.at(0).get('key1')); // Prints 1 as a result of model-level data collation
   * console.log(colStore2.at(3).get('id')); // Prints 10 as a result of collection-level data collation
   *
   */
  getCollectionStore(key, options) {
    return this.#storeImpl.getCollection(key, options);
  }
  
  /**
   * Ensures the storage API is ready. Usually called by core part of the application framework.
   *
   * @returns {jQuery.Promise<void>} Returns a promise that resolves when the store's API is ready for consumption
   */
  ensureStore() {
    return this.#storeImpl.ensureStore();
  }
  
  /**
   * Deletes all saved data from the store and re-initializes itself with blank state. This API call has to be followed by an application reload
   * so that Model and Collection stores can begin from their expected default state. It is usually called by the application framework when user
   * wants to discard their personalization data.
   *
   * @returns {jQuery.Promise<void>} Returns a promise that resolves upon successful reset
   */
  resetStore() {
    return this.#storeImpl.resetStore();
  }
}

Object.defineProperty(PersistentStore.prototype.constructor, 'name', {value: 'PersistentStore'});

/**
 * Options for retrieving a model store
 *
 * @typedef {Object} ModelStoreOptions
 * @param {Boolean} [create=false] - Do not create a store if it does not exist already.
 * @param {Object} [defaultValues={}] - Initialization/collation parameters to be used for the store. This is an option hash and can contain any
 * arbitrary number of key-value pairs. If a matching key does not already exist in the store, it will be put in the store with given value, otherwise the key is ignored.
 */

/**
 * Options for retrieving a collection store
 *
 * @typedef {Object} CollectionStoreOptions
 * @param {Boolean} [create=false] - Do not create a store if it does not exist already.
 * @param {Object} [defaultValues=[]] - Initialization/collation parameters to be used for the store. This is an array of arbitrary option object such that the objects are simple key-value
 * pairs. The objects in `defaultValues` are placed/evaluated in the store by maintaining their positional order such that if there are more objects
 * then additional models are created within the store to match its length with the option's. However, if there are fewer objects in the option, then stored models are not removed.
 * For each object in this option, the stored models are unidirectionally collated with key-value pairs from the corresponding object such that, if a key from the object is absent in
 * the corresponding model, the key is created within the model with supplied value. But, for existing keys the stored value is retained ignoring the value provided in options.
 */

/**
 * @alias "module:dctmw/utils/persistent.store"
 * @type {Readonly<PersistentStore>}
 *
 * @example <caption>Typical usage</caption>
 * import persistentStore from 'dctmw/utils/persistent.store';
 *
 * const myPersistedModel = persistentStore.getModelStore('my_data');
 *
 */
const storeInstance = Object.freeze(new PersistentStore());
export default storeInstance;

/**
 * @external BackboneModel
 * @see https://backbonejs.org/#Model
 */

/**
 * @external BackboneCollection
 * @see https://backbonejs.org/#Collection
 */
