csui.define('dctmw/controls/signin/location.view',[
  'nuc/lib/marionette'
], function (Marionette) {
  'use strict';

  var LocationItemView = Marionette.ItemView.extend({
    tagName: 'option',
    className: 'signin-option',

    template: false,
    onRender: function () {
      var locationName = this.model.get('network_name'),
          locationId = this.model.get('id');
      this.$el.text(locationName);
      this.$el.val(locationId);
    }
  });

  return LocationItemView;
});