// import CsuiJatoBrandingIcons from 'csui/themes/csui.jato.branding.icons'; //not present in bundle index, so getting treated as private file
import extBrandingIcons from 'dctm-ext!dctmw/utils/icons/dctmw.jato.branding';

const DctmwJatoStatusIcons = {}; //{...CsuiJatoBrandingIcons};

extBrandingIcons?.forEach((ext) => {
  Object.entries(ext).filter(([k, _]) => !['_srcModule', '_srcNS'].includes(k)).forEach(([k, v]) => {
    !DctmwJatoStatusIcons[k] && (DctmwJatoStatusIcons[k] = v); //let's forcefully keep the original icons
  });
});
export default DctmwJatoStatusIcons;


