csui.define('dctmw/controls/signin/location.list.view',[
  'nuc/lib/marionette',
  'dctmw/controls/signin/location.view'
], function (Marionette, LocationItemView) {
  'use strict';

  var LocationListView = Marionette.CollectionView.extend({
    tagName: 'select',
    tabindex: '0',
    childView: LocationItemView,
    className: 'location-select',
    attributes: { "aria-label": "Select a network location", "required": "required" }
  });

  return LocationListView;
});